import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  computed,
  Directive,
  forwardRef,
  inject,
  input,
  model,
} from '@angular/core';
import { cn } from '@loomui/ui/utils';
import {
  UI_MENU_CTX,
  UI_MENU_ITEM,
  UI_MENU_SUB,
  UiMenuItemBase,
  UiMenuSubBase,
  UiMenuSubTriggerBase,
  UiMenuContentBase,
