import { menubarItemClass, menubarSubTriggerClass, menubarSeparatorClass, menubarShortcutClass, menubarContentClass } from './menubar';
import { UiElementHost } from '@loomui/ui/utils';

export { UiMenuSelectEvent };

const ITEM_CLASS = menubarItemClass;
const SUB_TRIGGER_CLASS = menubarSubTriggerClass;
const CHECKBOX_CLASS = contextMenuCheckboxItemClass.replace(/context-menu/g, 'menubar');
const RADIO_CLASS = contextMenuRadioItemClass.replace(/context-menu/g, 'menubar');
const LABEL_CLASS = contextMenuLabelClass.replace(/context-menu/g, 'menubar');
const SEPARATOR_CLASS = menubarSeparatorClass;
const SHORTCUT_CLASS = menubarShortcutClass;
const CONTENT_CLASS = menubarContentClass;

@Directive({
  selector: '[uiMenubarItem], ui-menubar-item', hostDirectives: [UiElementHost],
  providers: [{ provide: UI_MENU_ITEM, useExisting: forwardRef(() => UiMenubarItem) }],
  host: {
    tabindex: '-1',
    '[attr.data-disabled]': 'disabled ? "" : null',
    '[attr.aria-disabled]': 'disabled ? "true" : null',
    '[attr.data-highlighted]': 'highlighted() ? "" : null',
    '(focus)': 'onFocus()',
    '(blur)': 'onBlur()',
    '(pointermove)': 'onPointerMove()',
    '(pointerleave)': 'onPointerLeave()',
    '(click)': 'activate()',
    'data-slot': 'menubar-item',
    role: 'menuitem',
    '[attr.data-variant]': 'variant()',
    '[attr.data-inset]': 'inset() ? "" : null',
    '[attr.class]': 'classes()',
  },
})
export class UiMenubarItem extends UiMenuItemBase {
  readonly variant = input<'default' | 'destructive'>('default');
  readonly inset = input(false, { transform: booleanAttribute });
  protected readonly classes = computed(() => cn(ITEM_CLASS, this.userClass()));
}

const CHECK =
  '<svg uiIcon="check" class="size-4"></svg>';

@Component({
  selector: '[uiMenubarCheckboxItem], ui-menubar-checkbox-item', hostDirectives: [UiElementHost],
  imports: [UiIconSvg],
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [{ provide: UI_MENU_ITEM, useExisting: forwardRef(() => UiMenubarCheckboxItem) }],
  host: {
    tabindex: '-1',
    '[attr.data-disabled]': 'disabled ? "" : null',
    '[attr.aria-disabled]': 'disabled ? "true" : null',
    '[attr.data-highlighted]': 'highlighted() ? "" : null',
    '(focus)': 'onFocus()',
    '(blur)': 'onBlur()',
    '(pointermove)': 'onPointerMove()',
    '(pointerleave)': 'onPointerLeave()',
    '(click)': 'activate()',
    'data-slot': 'menubar-checkbox-item',
    role: 'menuitemcheckbox',
    '[attr.aria-checked]': 'checked()',
    '[attr.data-state]': 'checked() ? "checked" : "unchecked"',
    '[attr.data-inset]': 'inset() ? "" : null',
    '[attr.class]': 'classes()',
  },
  template: `
    <ng-content />
    <span class="pointer-events-none absolute end-2 flex items-center justify-center" data-slot="menubar-checkbox-item-indicator">
      @if (checked()) { ${CHECK} }
    </span>
  `,
})
export class UiMenubarCheckboxItem extends UiMenuItemBase {
  readonly checked = model(false);
  readonly inset = input(false, { transform: booleanAttribute });
  protected readonly classes = computed(() => cn(CHECKBOX_CLASS, this.userClass()));
  protected override beforeSelect(): void {
    this.checked.update((v) => !v);
  }
}

@Directive({
  selector: '[uiMenubarRadioGroup], ui-menubar-radio-group', hostDirectives: [UiElementHost],
  host: { role: 'group', 'data-slot': 'menubar-radio-group' },
})
export class UiMenubarRadioGroup {
  readonly value = model<string | undefined>(undefined);
}

@Component({
  selector: '[uiMenubarRadioItem], ui-menubar-radio-item', hostDirectives: [UiElementHost],
  imports: [UiIconSvg],
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [{ provide: UI_MENU_ITEM, useExisting: forwardRef(() => UiMenubarRadioItem) }],
  host: {
    tabindex: '-1',
    '[attr.data-disabled]': 'disabled ? "" : null',
    '[attr.aria-disabled]': 'disabled ? "true" : null',
    '[attr.data-highlighted]': 'highlighted() ? "" : null',
    '(focus)': 'onFocus()',
    '(blur)': 'onBlur()',
    '(pointermove)': 'onPointerMove()',
    '(pointerleave)': 'onPointerLeave()',
    '(click)': 'activate()',
    'data-slot': 'menubar-radio-item',
    role: 'menuitemradio',
    '[attr.aria-checked]': 'checked()',
    '[attr.data-state]': 'checked() ? "checked" : "unchecked"',
    '[attr.data-inset]': 'inset() ? "" : null',
    '[attr.class]': 'classes()',
  },
  template: `
    <ng-content />
    <span class="pointer-events-none absolute end-2 flex items-center justify-center" data-slot="menubar-radio-item-indicator">
      @if (checked()) { ${CHECK} }
    </span>
  `,
})
export class UiMenubarRadioItem extends UiMenuItemBase {
  private readonly group = inject(UiMenubarRadioGroup);
  readonly value = input<string>('');
  readonly inset = input(false, { transform: booleanAttribute });
  protected readonly checked = computed(() => this.group.value() === this.value());
  protected readonly classes = computed(() => cn(RADIO_CLASS, this.userClass()));
  protected override beforeSelect(): void {
    this.group.value.set(this.value());
  }
}

/** Sub-menu: <div uiMenubarSub><div uiMenubarSubTrigger>More</div><div uiMenubarSubContent>…</div></div> */
@Directive({
  selector: '[uiMenubarSub], ui-menubar-sub', hostDirectives: [UiElementHost],
  providers: [
    { provide: UI_MENU_CTX, useExisting: forwardRef(() => UiMenubarSub) },
    { provide: UI_MENU_SUB, useExisting: forwardRef(() => UiMenubarSub) },
  ],
})
export class UiMenubarSub extends UiMenuSubBase {}

@Component({
  selector: '[uiMenubarSubTrigger], ui-menubar-sub-trigger', hostDirectives: [UiElementHost],
  imports: [UiIconSvg],
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [{ provide: UI_MENU_ITEM, useExisting: forwardRef(() => UiMenubarSubTrigger) }],
  host: {
    tabindex: '-1',
    '[attr.data-disabled]': 'disabled ? "" : null',
    '[attr.aria-disabled]': 'disabled ? "true" : null',
    '[attr.data-highlighted]': 'highlighted() ? "" : null',
    '(focus)': 'onFocus()',
    '(blur)': 'onBlur()',
    '(pointermove)': 'onPointerMove()',
    '(pointerleave)': 'onPointerLeave()',
    '(click)': 'activate()',
    'data-slot': 'menubar-sub-trigger',
    role: 'menuitem',
    'aria-haspopup': 'menu',
    '[attr.aria-expanded]': 'sub.open()',
    '[attr.data-state]': 'sub.open() ? "open" : "closed"',
    '[attr.data-inset]': 'inset() ? "" : null',
