  template: `
    <ng-content />
    <svg uiIcon="chevron-right" class="ms-auto rtl:rotate-180"></svg>
  `,
})
export class UiMenubarSubTrigger extends UiMenuSubTriggerBase {
  readonly inset = input(false, { transform: booleanAttribute });
  protected readonly classes = computed(() => cn(SUB_TRIGGER_CLASS, this.userClass()));
}

@Directive({
  selector: '[uiMenubarSubContent], ui-menubar-sub-content', hostDirectives: [UiElementHost],
  host: {
    role: 'menu',
    'aria-orientation': 'vertical',
    'data-slot': 'menubar-sub-content',
    tabindex: '-1',
    '[attr.data-state]': 'root.state()',
    '[attr.dir]': 'dir.value',
    '[attr.class]': 'classes()',
    '(keydown)': 'onMenuKeydown($event)',
  },
})
export class UiMenubarSubContent extends UiMenuContentBase {
  protected readonly root = inject(UiMenubarSub);
  protected readonly menu = this.root;
  protected readonly varPrefix = '--radix-menubar';
  override readonly side = input<'top' | 'right' | 'bottom' | 'left'>('right');
  override readonly align = input<Align>('start');
  override readonly sideOffset = input(0);
  private readonly items = contentChildren<UiMenuItemBase>(UI_MENU_ITEM, { descendants: true });
  protected readonly classes = computed(() => cn(CONTENT_CLASS, 'w-auto', this.userClass()));
  protected menuItems(): readonly UiMenuItemBase[] {
    return this.items();
  }
  constructor() {
    super();
    this.isSub = true;
    this.init();
  }
}

@Directive({
  selector: '[uiMenubarLabel], ui-menubar-label', hostDirectives: [UiElementHost],
  host: { 'data-slot': 'menubar-label', '[attr.data-inset]': 'inset() ? "" : null', '[attr.class]': 'classes()' },
})
export class UiMenubarLabel {
  readonly inset = input(false, { transform: booleanAttribute });
  readonly userClass = input<string>('', { alias: 'class' });
  protected readonly classes = computed(() => cn(LABEL_CLASS, this.userClass()));
}

